'use strict';
window.FAG_GEOGRAFI = {
  name:'Geografi', icon:'🌍', color:'#0891b2',
  description:'Klima, natur, befolkning og globale sammenhænge – fra lokalmiljøet til verdensøkonomien.',
  levels:{
    '0-3':{
      title:'0–3. klasse',
      description:'Vores nærmiljø, vejret og den store verden.',
      topics:[
        {id:'geo03-1',title:'Mit nabolag',icon:'🏘️',tags:['nabolag','gade','hjem'],body:`<div class="def-box">Et nabolag er området rundt om der hvor vi bor. Det har gader, bygninger, parker og butikker. Hvad er der i dit nabolag?</div>`},
        {id:'geo03-2',title:'By og land',icon:'🌆',tags:['by','land','forskel'],body:`<div class="def-box">I en <strong>by</strong> er der mange huse, butikker og trafik. På <strong>landet</strong> er der marker, natur og færre mennesker.</div>`},
        {id:'geo03-3',title:'Kortlæsning – intro',icon:'🗺️',tags:['kort','symbol','retning'],body:`<div class="def-box">Et kort er et billede af jordens overflade set ovenfra. Kortet bruger symboler til at vise veje, huse og natur.</div>`},
        {id:'geo03-4',title:'Verdenshjørnerne',icon:'🧭',tags:['nord','syd','øst','vest'],body:`<div class="formula-box">Nord · Syd · Øst · Vest</div><p>Kompasset viser os retninger. Solen går op i øst og ned i vest.</p>`},
        {id:'geo03-5',title:'Vejret',icon:'☀️',tags:['sol','regn','vind'],body:`<div class="def-box">Vejret fortæller os om det er sol, regn, vind eller sne udenfor. Det ændrer sig fra dag til dag.</div>`},
        {id:'geo03-6',title:'Årstiderne',icon:'🍂',tags:['forår','sommer','efterår','vinter'],body:`<div class="formula-box">Forår 🌸 → Sommer ☀️ → Efterår 🍂 → Vinter ❄️</div><p>Årstiderne ændrer vejret og naturen over et år.</p>`},
        {id:'geo03-7',title:'Danmark',icon:'🇩🇰',tags:['Danmark','Jylland','øer'],body:`<div class="def-box">Danmark består af Jylland (halvøen) og mange øer. Sjælland og Fyn er de største øer. København er vores hovedstad.</div>`},
        {id:'geo03-8',title:'Havet og vandløb',icon:'🌊',tags:['hav','å','sø'],body:`<div class="def-box">Danmark er omgivet af hav. Vi har også søer og åer. Vand er vigtigt for alt liv og for menneskelige aktiviteter.</div>`},
        {id:'geo03-9',title:'Verdensdelene',icon:'🌍',tags:['Europa','Afrika','Amerika'],body:`<div class="formula-box">Europa · Asien · Afrika · Nord- og Sydamerika · Australien · Antarktis</div>`},
        {id:'geo03-10',title:'Lande og flag',icon:'🏳️',tags:['land','flag','nationalitet'],body:`<div class="def-box">Hvert land har sit eget flag og navn. Danmark er et land. Det røde flag med det hvide kors hedder Dannebrog.</div>`},
        {id:'geo03-11',title:'Naturen i Danmark',icon:'🌲',tags:['skov','strand','mark'],body:`<div class="def-box">Danmark har skove, strande, marker og heder. Vi passer på naturen så den er der til fremtidige generationer.</div>`},
        {id:'geo03-12',title:'Bjerge og sletter',icon:'⛰️',tags:['bjerg','slette','bakke'],body:`<div class="def-box">Bjerge er høje landmasser. Sletter er flade og lave. Danmark er mest fladt. Himalaya er verdens højeste bjergkæde.</div>`},
        {id:'geo03-13',title:'Regn og tørke',icon:'🌧️',tags:['regn','tørke','vand'],body:`<div class="def-box">Regn giver planter og dyr vand. Tørke er når der ikke regner i lang tid. I ørkener regner det meget lidt.</div>`},
        {id:'geo03-14',title:'Dyreliv rundt om verden',icon:'🦁',tags:['safari','pingvin','dyr'],body:`<div class="def-box">Forskellige dyr lever på forskellige steder: løver i Afrika, pingviner ved sydpolen, isbjørne i Arktis. Hvert dyr er tilpasset sit miljø.</div>`},
        {id:'geo03-15',title:'Planter rundt om verden',icon:'🌴',tags:['palme','kaktus','nåletræ'],body:`<div class="def-box">Tropebjerne: palmer og store træer. Ørkener: kaktusser. Kolde lande: nåletræer. Planter tilpasser sig klimaet.</div>`},
        {id:'geo03-16',title:'Mad fra hele verden',icon:'🌮',tags:['mad','kultur','land'],body:`<div class="def-box">Mennesker rundt om verden spiser forskellig mad: pasta fra Italien, sushi fra Japan, tacos fra Mexico. Mad er del af kulturarven.</div>`},
        {id:'geo03-17',title:'Transport',icon:'🚗',tags:['bil','fly','skib'],body:`<div class="def-box">Vi bruger transport til at bevæge os: biler på vejene, tog på skinnerne, skibe på havet og fly i luften.</div>`},
        {id:'geo03-18',title:'Ressourcer fra naturen',icon:'🌾',tags:['ressource','mad','vand'],body:`<div class="def-box">Vi bruger naturressourcer: madvarer fra marker, træ fra skove, vand fra åer og søer. Vi skal bruge dem med omtanke.</div>`},
        {id:'geo03-19',title:'Forurening',icon:'🏭',tags:['forurening','røg','plastik'],body:`<div class="def-box">Forurening skader naturen: røg fra fabrikker, plastik i havet, pesticider i marken. Vi kan hjælpe ved at genbruge og spare energi.</div>`},
        {id:'geo03-20',title:'Familien og boligen',icon:'🏠',tags:['familie','bolig','hus'],body:`<div class="def-box">Mennesker bor mange steder: huse, lejligheder, hytter. I kolde lande er husene isolerede. I varme lande er de åbne og luftige.</div>`},
        {id:'geo03-21',title:'Skolen',icon:'🏫',tags:['skole','lære','elev'],body:`<div class="def-box">Børn i hele verden går i skole for at lære. Skolerne er forskellige: nogle er store bygninger, andre er under åben himmel.</div>`},
        {id:'geo03-22',title:'Globus og jordkloden',icon:'🌐',tags:['globus','kugle','planet'],body:`<div class="def-box">Jordens form er en kugle. En globus er en model af Jordens overflade. Flader er bøjet, mens et kort er fladt.</div>`},
        {id:'geo03-23',title:'Sollys og temperatur',icon:'🌡️',tags:['sol','varme','temperatur'],body:`<div class="def-box">Steder tæt på ækvator får meget sollys og er varme. Polen er kolde fordi solens lys rammer dem mere skråt.</div>`},
        {id:'geo03-24',title:'Vind',icon:'💨',tags:['vind','storm','kuling'],body:`<div class="def-box">Vind er luft der bevæger sig. Det sker fordi luft bevæger sig fra højtryk til lavtryk. Vind kan drive vindmøller og sejlbåde.</div>`},
        {id:'geo03-25',title:'Floder og søer',icon:'🏞️',tags:['flod','sø','ferskvand'],body:`<div class="def-box">Floder løber ned mod havet. Søer er stillestående vand omgivet af land. Begge er ferskvandskilder for dyr, planter og mennesker.</div>`},
        {id:'geo03-26',title:'Øer',icon:'🏝️',tags:['ø','hav','afsondret'],body:`<div class="def-box">En ø er et landstykke omgivet af vand. Bornholm er en dansk ø. Island og Grønland er store øer.</div>`},
        {id:'geo03-27',title:'Europas lande',icon:'🇪🇺',tags:['Europa','naboland','grænse'],body:`<div class="def-box">Danmarks naboer: Tyskland mod syd, Sverige og Norge over havet. Europas store lande: Frankrig, Tyskland, Spanien, Italien.</div>`},
        {id:'geo03-28',title:'Klima og vejr',icon:'🌡️',tags:['klima','vejr','forskel'],body:`<div class="def-box">Klima er gennemsnitligt vejr over mange år. Vejr er dag-til-dag forandringer. Danmark har et tempereret klima med alle årstider.</div>`},
        {id:'geo03-29',title:'Landbrug og mad',icon:'🚜',tags:['landbrug','marker','mad'],body:`<div class="def-box">Landmænd dyrker marker med korn, grøntsager og frugt. Kvæg og svin producerer kød og mælk. Danmark eksporterer meget mad.</div>`},
        {id:'geo03-30',title:'Miljøbeskyttelse',icon:'♻️',tags:['genbruge','beskytte','natur'],body:`<div class="def-box">Vi beskytter miljøet ved at genbruge, spare på vand og el, og undgå at smide affald i naturen. Alle kan bidrage!</div>`},
      ]
    },
    '4-6':{
      title:'4–6. klasse',
      description:'Klima, befolkning, ressourcer og kontinenter.',
      topics:[
        {id:'geo46-1',title:'Jordens opbygning',icon:'🌍',tags:['jordskorpe','mantel','kerne'],body:`<div class="def-box">Jordskorpe (0–70 km) → Mantel (flydende sten) → Ydre kerne (flydende jern) → Indre kerne (fast jern). Indre temperatur: ~5500°C.</div>`},
        {id:'geo46-2',title:'Pladetektonik',icon:'🌋',tags:['tektonisk plade','kontinent','bevægelse'],body:`<div class="def-box">Jordens overflade består af tektoniske plader der bevæger sig ~2-10 cm/år. Pladegrænserne giver jordskælv og vulkaner.</div>`},
        {id:'geo46-3',title:'Jordskælv',icon:'🏚️',tags:['jordskælv','Richter','epicenter'],body:`<div class="def-box">Jordskælv opstår når tektoniske plader gliber. Richter-skalaen måler styrken (logaritmisk). Epicentret er det overfladiske centrum.</div>`},
        {id:'geo46-4',title:'Vulkaner',icon:'🌋',tags:['vulkan','lava','magma'],body:`<div class="def-box">Vulkaner udbyder magma fra jordens indre. Island sidder på en spredezonegrænse og har mange aktive vulkaner. Lava kan forme nye landmasser.</div>`},
        {id:'geo46-5',title:'Klimazoner',icon:'🌡️',tags:['klima','trope','arktis'],body:`<div class="formula-box">Arktisk → Subarktisk → Tempereret → Subtropisk → Tropisk</div><p>Klimaet varierer med breddegrad og afstand til hav.</p>`},
        {id:'geo46-6',title:'Ørken',icon:'🏜️',tags:['ørken','tørke','Sahara'],body:`<div class="def-box">Ørkener: under 250 mm nedbør/år. Sahara er verdens største varme ørken. Antarktis er verdens største kolde ørken. Tilpasninger: lavt vandforbrug.</div>`},
        {id:'geo46-7',title:'Regnskov',icon:'🌴',tags:['regnskov','Amazonas','biodiversitet'],body:`<div class="def-box">Tropisk regnskov: høj temperatur, over 2000 mm regn/år. Amazonas: verdens største regnskov. Hjem for over 50% af alle jordiske arter.</div>`},
        {id:'geo46-8',title:'Savanne',icon:'🌾',tags:['savanne','Afrika','tørketid'],body:`<div class="def-box">Savanne: åbent græsland med spredte træer i tropiske og subtropiske egne. Tydelig tørtid. Kendetegnet ved store planteædere (elefanter, giraffer).</div>`},
        {id:'geo46-9',title:'Nåleskov og tundra',icon:'🌲',tags:['taiga','tundra','borealt'],body:`<div class="def-box">Taiga (boreal skov): den største terrestriske biom – nåletræer i Russland, Canada. Tundra: permanent frossen jord (permafrost), ingen træer.</div>`},
        {id:'geo46-10',title:'Verdens befolkning',icon:'👥',tags:['befolkning','vækst','milliarder'],body:`<div class="def-box">Verdens befolkning: ca. 8 milliarder (2023). Vokser med ~80 millioner/år. Mest vækst i Afrika og Asien. Demografisk overgang beskriver vækstmønstre.</div>`},
        {id:'geo46-11',title:'Migration',icon:'✈️',tags:['migration','flygtning','indvandrer'],body:`<div class="def-box">Migration: flytning af folk fra ét sted til et andet. Push-faktorer: krig, fattigdom, klimaforandringer. Pull-faktorer: job, sikkerhed, familie.</div>`},
        {id:'geo46-12',title:'Urbanisering',icon:'🏙️',tags:['by','urbanisering','megaby'],body:`<div class="def-box">Urbanisering: folk flytter fra land til by. Globalt bor over 55% i byer. Megabyer (>10 mio.): Tokyo, Shanghai, Delhi.</div>`},
        {id:'geo46-13',title:'Vand som ressource',icon:'💧',tags:['ferskvand','vandmangel','grundvand'],body:`<div class="def-box">Kun 3% af jordenes vand er ferskvand, og det meste er frosset. Grundvand og floder er de vigtigste drikkevandskilder. Mange regioner lider af vandmangel.</div>`},
        {id:'geo46-14',title:'Energiressourcer',icon:'⚡',tags:['fossil','vedvarende','energi'],body:`<div class="def-box">Fossile brændstoffer (kul, olie, gas): ikke-vedvarende, udleder CO₂. Vedvarende: sol, vind, vand, geotermisk. Transitionen er afgørende for klimaet.</div>`},
        {id:'geo46-15',title:'Mineraler og råstoffer',icon:'💎',tags:['mineral','minedrift','sjælden'],body:`<div class="def-box">Mineraler bruges i elektronik (lithium, kobolt), bygning (jern, kalk) og smykker (guld, diamant). Minedrift kan skade miljøet lokalt.</div>`},
        {id:'geo46-16',title:'Landbrug og fødevarer',icon:'🌾',tags:['landbrug','korn','eksport'],body:`<div class="def-box">Moderne landbrug: mekanisering, kunstgødning, pesticider. Udfordringer: jorderosion, vandforbrug, klimaforandringer. Bæredygtigt landbrug er en løsning.</div>`},
        {id:'geo46-17',title:'Handel og globalisering',icon:'🚢',tags:['handel','import','eksport'],body:`<div class="def-box">Lande handler med hinanden. Import: varer vi køber udefra. Eksport: varer vi sælger til udlandet. Danmark eksporterer bacon, medicin og vindmøller.</div>`},
        {id:'geo46-18',title:'Afrika',icon:'🌍',tags:['Afrika','Sahara','lande'],body:`<div class="def-box">Afrika er verdens næststørste kontinent. 54 lande. Sahara deler nord og syd. Store floder: Nil, Kongo, Niger. Højt befolkningsvækst.</div>`},
        {id:'geo46-19',title:'Asien',icon:'🌏',tags:['Asien','Kina','Himalaya'],body:`<div class="def-box">Asien er verdens største kontinent. Kina og Indien har mest befolkning. Himalaya: verdens højeste bjerge. Store floder: Yangtze, Ganges, Mekong.</div>`},
        {id:'geo46-20',title:'Amerika',icon:'🌎',tags:['USA','Amazonas','Andes'],body:`<div class="def-box">Nordamerika: USA, Canada, Mexico. Sydamerika: Brasilien, Argentina, Colombia. Andes: verdens længste bjergkæde. Amazonas: verdens største flod.</div>`},
        {id:'geo46-21',title:'Australien og Oceanien',icon:'🦘',tags:['Australien','koala','Great Barrier Reef'],body:`<div class="def-box">Australien er det mindste kontinent. Unikke dyr: kænguru, koala, wombat. Great Barrier Reef: verdens største koralsystem. Tørre indre (outback).</div>`},
        {id:'geo46-22',title:'Arktis og Antarktis',icon:'🐧',tags:['Arktis','Antarktis','is'],body:`<div class="def-box">Arktis: ishav omgivet af land (isbjørne). Antarktis: kontinent dækket af is (pingviner). Begge smelter pga. klimaforandringer.</div>`},
        {id:'geo46-23',title:'Havet og oceanerne',icon:'🌊',tags:['ocean','strøm','bundforhold'],body:`<div class="def-box">5 oceaner: Stillehavet (størst), Atlanterhavet, Indiske Ocean, Sydhavet, Arktiske Ocean. Havstrømme regulerer klimaet globalt.</div>`},
        {id:'geo46-24',title:'Naturkatastrofer',icon:'⚡',tags:['orkan','tsunami','tornado'],body:`<div class="def-box">Naturkatastrofer: jordskælv, tsunamier, orkaner, oversvømmelser, vulkanudbrud, tørke. Sårbarhed afhænger af placering og beredskab.</div>`},
        {id:'geo46-25',title:'Klimaforandringer – årsager',icon:'🌡️',tags:['CO₂','drivhuseffekt','global opvarmning'],body:`<div class="def-box">Menneskelig udledning af CO₂ (fossile brændstoffer) og metan (landbrug) forstærker drivhuseffekten → global opvarmning → klimaforandringer.</div>`},
        {id:'geo46-26',title:'Klimaforandringer – konsekvenser',icon:'🌊',tags:['havstigning','vejr','ekstremt'],body:`<div class="def-box">Konsekvenser: stigende havniveau (smeltende gletschere), mere ekstreme vejrhændelser, arters uddøen, havsuring, vandmangel.</div>`},
        {id:'geo46-27',title:'Bæredygtig udvikling',icon:'♻️',tags:['FN','SDG','bæredygtighed'],body:`<div class="def-box">FN's 17 verdensmål (SDG) sigter mod bæredygtig udvikling: fattigdomsbekæmpelse, ren energi, klimahandling, retfærdighed. Alle lande er forpligtet.</div>`},
        {id:'geo46-28',title:'Nationalparker',icon:'🏞️',tags:['nationalpark','naturbeskyttelse','biodiversitet'],body:`<div class="def-box">Nationalparker beskytter naturen mod menneskelig indgriben. Yellowstone, Amazon-nationalparker og Galápagos er verdenskendte eksempler.</div>`},
        {id:'geo46-29',title:'Kystlandskaber',icon:'🏖️',tags:['kyst','klint','delta'],body:`<div class="def-box">Kysttyper: sandstrand, klint (stejl stejlkyst), delta (flodmunding), fjord (isformet dal). Erosion og aflejring former kysterne over tid.</div>`},
        {id:'geo46-30',title:'Det globale vejrsystem',icon:'🌀',tags:['jet stream','monsun','lavtryk'],body:`<div class="def-box">Monsun: sæsonbestemt vindmønster med rigelige regn (Sydasien, Vestafrika). Jet stream: hurtige vinde i stratosfæren der styrer vejrsystemer.</div>`},
      ]
    },
    '7-9':{
      title:'7–9. klasse',
      description:'Globaløkonomi, geopolitik, klima og demografiske mønstre.',
      topics:[
        {id:'geo79-1',title:'Demografisk overgang',icon:'📊',tags:['fertilitet','mortalitet','overgang'],body:`<div class="def-box">Model i 4 faser: Høj fertilitet + høj mortalitet → Faldende mortalitet → Faldende fertilitet → Lav fertilitet + lav mortalitet. De fleste u-lande er i fase 2-3.</div>`},
        {id:'geo79-2',title:'BNP og udvikling',icon:'💰',tags:['BNP','HDI','fattigdom'],body:`<div class="def-box">BNP (Bruttonationalprodukt): samlet produktion/indkomst i et land. HDI (Human Development Index): måler BNP, uddannelse og forventet levealder.</div>`},
        {id:'geo79-3',title:'Globale uligheder',icon:'⚖️',tags:['nord-syd','fattigdom','u-land'],body:`<div class="def-box">Global ulighed: den rigeste 1% ejer ~43% af verdens formue. Nord-Syd-kløft: industrialiserede kontra udviklende lande. Brandt-linjen illustrerer opdeling.</div>`},
        {id:'geo79-4',title:'Kolonialisme og dens eftervirkninger',icon:'📜',tags:['koloni','imperialisme','uafhængighed'],body:`<div class="def-box">Europæiske magter koloniserede store dele af verden 1400-1900. Kolonialisme: ressourceudtrækning, kulturundertrykkelse. Eftervirkninger: grænser, politisk ustabilitet.</div>`},
        {id:'geo79-5',title:'Globalisering',icon:'🌐',tags:['globalisering','handel','kultur'],body:`<div class="def-box">Globalisering: øget forbundethed via handel, kommunikation og migration. Fordele: vækst, kulturudveksling. Ulemper: ulighed, miljøbelastning, kulturhomogenisering.</div>`},
        {id:'geo79-6',title:'Multinationale selskaber',icon:'🏢',tags:['multinational','Apple','indflydelse'],body:`<div class="def-box">Multinationale selskaber (Apple, Shell, Toyota) opererer i mange lande. De har enorm økonomisk og politisk indflydelse, men kritiseres for skatteundgåelse og lave lønninger.</div>`},
        {id:'geo79-7',title:'Handelssystemer og WTO',icon:'📦',tags:['WTO','told','frihandel'],body:`<div class="def-box">WTO (World Trade Organization) regulerer international handel. Frihandel: lavere toldbarrierer = mere handel. Protektionisme: told og kvoter beskytter nationale industrier.</div>`},
        {id:'geo79-8',title:'Klimaaftaler – Paris-aftalen',icon:'🌡️',tags:['Paris','klimaaftale','2°C'],body:`<div class="def-box">Paris-aftalen (2015): 195 lande forpligtet til at begrænse opvarmning til under 2°C (mål: 1,5°C). Nationale mål (NDC) skal strammes regelmæssigt.</div>`},
        {id:'geo79-9',title:'Energitransition',icon:'🌬️',tags:['vedvarende','fossil','grøn'],body:`<div class="def-box">Energitransition: skift fra fossile brændstoffer til vedvarende energi (sol, vind, brint). Teknologi og politisk vilje er afgørende faktorer.</div>`},
        {id:'geo79-10',title:'Vandmangel og vandkrig',icon:'💧',tags:['vandmangel','konflikt','grundvand'],body:`<div class="def-box">Over 2 milliarder mennesker mangler rent drikkevand. Nilen, Jordan og Mekong er omstridte floder. Fremtidige konflikter kan udløses af vandmangel.</div>`},
        {id:'geo79-11',title:'Fødevaresikkerhed',icon:'🍚',tags:['sult','mad','distribution'],body:`<div class="def-box">Globalt produceres nok mad, men distribution er ulige. 800 mio. sulter, mens 1,3 mia. ton mad spildes/år. Klimaforandringer truer fremtidig produktion.</div>`},
        {id:'geo79-12',title:'Urbanisering og slumkvarterer',icon:'🏙️',tags:['slum','megaby','urbanisering'],body:`<div class="def-box">Hurtig urbanisering i udviklingslande → slumkvarterer (favelas, shanty towns). Dårlig infrastruktur, ringe sanitering og kriminalitet er typiske problemer.</div>`},
        {id:'geo79-13',title:'Migration og asyl',icon:'🚢',tags:['asyl','flygtning','1951-konvention'],body:`<div class="def-box">1951-konventionen: FN's flygtningedefinition. Klimaflygtninge er juridisk uanerkendte. Migration driver vækst men skaber også politiske spændinger.</div>`},
        {id:'geo79-14',title:'Geopolitik og supermagter',icon:'🌍',tags:['USA','Kina','Rusland'],body:`<div class="def-box">Geopolitik: staters interesser formes af geografi. USA: militær og teknologisk supermagt. Kina: voksende økonomisk magt. Rusland: energieksportør og militær aktør.</div>`},
        {id:'geo79-15',title:'Terrorisme og konflikter',icon:'⚠️',tags:['terrorisme','konflikt','geopolitik'],body:`<div class="def-box">Terrorisme er politisk motiveret vold mod civile. Mellemøsten er konfliktpræget pga. ressourcer, religion og politiske grænser tegnet af kolonister.</div>`},
        {id:'geo79-16',title:'FN og internationale organisationer',icon:'🕊️',tags:['FN','NATO','AU'],body:`<div class="def-box">FN: verdens fredsorganisation med 193 lande. Sikkerhedsrådet (5 vetomagter). NATO: militærforbund. AU: Afrikansk Union. WTO: handel. WHO: sundhed.</div>`},
        {id:'geo79-17',title:'Skovskade – afskovning',icon:'🪓',tags:['afskovning','regnskov','CO₂'],body:`<div class="def-box">Afskovning: tropiske regnskove ryddes til landbrug og skovbrug. Brasilien, Indonesien og DRC har højest tab. Frigiver CO₂ og ødelægger habitater.</div>`},
        {id:'geo79-18',title:'Plastikforurening',icon:'🐢',tags:['plastik','hav','mikroplastik'],body:`<div class="def-box">Plastik akkumuleres i havenes Great Pacific Garbage Patch. Mikroplastik findes i havdyr og drikkevand. Single-use plastik er et globalt problem.</div>`},
        {id:'geo79-19',title:'Biodiversitetskrise',icon:'🦋',tags:['uddøen','habitat','IPBES'],body:`<div class="def-box">Artsudslettelse sker 100-1000× hurtigere end naturligt. IPBES: 1 million arter trues. Årsager: habitattab, klimaforandringer, overudnyttelse.</div>`},
        {id:'geo79-20',title:'Landbrug og miljø',icon:'🚜',tags:['kunstgødning','pesticid','erosion'],body:`<div class="def-box">Intensivt landbrug: kunstgødning (kvælstof) → eutrofiering af søer. Pesticider dræber insekter. Monokulturer reducerer biodiversitet.</div>`},
        {id:'geo79-21',title:'Naturressourcer og økonomi',icon:'🛢️',tags:['olie','diamant','ressourceforbandelse'],body:`<div class="def-box">Ressourceforbandelse: lande rige på naturressourcer har ofte svag demokrati og høj ulighed (Nigeria, DRC). Ressourcerne tiltrækker korruption og konflikter.</div>`},
        {id:'geo79-22',title:'Turisme og bæredygtighed',icon:'✈️',tags:['turisme','overtourism','bæredygtig'],body:`<div class="def-box">Turisme er verdens største industri men belaster miljø og lokale kulturer. Overtourism (Venedig, Barcelonas) skader infrastruktur. Bæredygtig turisme minimerer skade.</div>`},
        {id:'geo79-23',title:'Landevejsbyggeri og infrastruktur',icon:'🛣️',tags:['infrastruktur','BRI','Kina'],body:`<div class="def-box">Infrastruktur er afgørende for udvikling. Kinas Belt and Road Initiative (BRI) finansierer infrastruktur i Afrika og Asien men kritiseres for gældsøkonomi.</div>`},
        {id:'geo79-24',title:'Smart cities',icon:'🏙️',tags:['smart city','teknologi','bæredygtig'],body:`<div class="def-box">Smart cities bruger teknologi til at optimere byens drift: sensorer, AI og data styrer trafik, energi og affald. Singapore og Barcelona er frontløbere.</div>`},
        {id:'geo79-25',title:'Kystbeskyttelse og havnivåstigning',icon:'🌊',tags:['hav','diger','oversvømmelse'],body:`<div class="def-box">Havniveaustigning truer lavtliggende øer og kystbyer. Bangladesh, Miami og Jakarta er sårbare. Diger, mangrove og flytning er løsninger.</div>`},
        {id:'geo79-26',title:'Gletschere og polaris',icon:'🧊',tags:['gletscher','isbjørne','meltning'],body:`<div class="def-box">Gletschere smelter globalt. Grønlandsis og Antarktis er de største isreserver. Smeltning bidrager til havniveaustigning og forstyrrer havstrømme.</div>`},
        {id:'geo79-27',title:'El Niño og La Niña',icon:'🌊',tags:['El Niño','La Niña','havtemperatur'],body:`<div class="def-box">El Niño: usædvanlig opvarmning af Stillehavet → ændrer vejrmønstre globalt → tørke i Australien, oversvømmelse i Peru. La Niña er det modsatte.</div>`},
        {id:'geo79-28',title:'Havsuring',icon:'🧪',tags:['CO₂','hav','koraller'],body:`<div class="def-box">CO₂ opløst i havvand → kulsyre (H₂CO₃) → lavere pH. Havet er 26% mere surt siden industrialiseringen. Truer koraller og havskaller.</div>`},
        {id:'geo79-29',title:'Solenergi – global fordeling',icon:'☀️',tags:['solenergi','Sahara','sol'],body:`<div class="def-box">De bedste solressourcer: Sahara, Mellemøsten, Australien, Chile. Solcellepaneler er billigst pr. kWh for mange lande. Kina dominerer produktion.</div>`},
        {id:'geo79-30',title:'Urbanisering i Kina og Indien',icon:'🏙️',tags:['Kina','Indien','vækst'],body:`<div class="def-box">Kina urbaniserede hurtigst i historien (1980-2020): 20%→60% bybeboere. Indien urbaniseres nu. Ghost cities og infrastrukturinvesteringer er karakteristiske.</div>`},
      ]
    },
    '10':{
      title:'10. klasse',
      description:'Avanceret klimaanalyse, udviklingsgeografi og ressourceøkonomi.',
      topics:[
        {id:'geo10-1',title:'Klimasystemer og feedback',icon:'🔄',tags:['albedo','feedback','tipping points'],body:`<div class="def-box">Positivt feedback: is smelter → lavere albedo → mere opvarmning. Tipping points: arktisk permafrost, Amazonas-kollaps, AMOC-svækkelse.</div>`},
        {id:'geo10-2',title:'Klimamodeller',icon:'💻',tags:['GCM','RCP','IPCC'],body:`<div class="def-box">IPCC bruger General Circulation Models (GCM) til at forudsige klimaet. RCP-scenarier (2.6, 4.5, 8.5) angiver CO₂-udledningsbaner og tilsvarende opvarmning.</div>`},
        {id:'geo10-3',title:'Klimaretfærdighed',icon:'⚖️',tags:['klimaretfærdighed','ulighed','ansvar'],body:`<div class="def-box">De lande der har udledt mindst CO₂ (u-lande) rammes hårdest af klimaforandringer. Klimaretfærdighed handler om kompensation og fordelingen af ansvar.</div>`},
        {id:'geo10-4',title:'Biodiversitet og ecosystem services',icon:'🌿',tags:['ecosystem services','biodiversitet','kapital'],body:`<div class="def-box">Ecosystem services: bestøvning (fødevarer), vandrensning, CO₂-binding, oversvømmelseshæmning. Biodiversitetstab reducerer disse services.</div>`},
        {id:'geo10-5',title:'Cirkulær økonomi',icon:'♻️',tags:['cirkulær','affald','genanvendelse'],body:`<div class="def-box">Cirkulær økonomi: produkter designes til genbrug, reparation og genanvendelse. Erstatter lineær "tag-brug-smid-væk"-økonomi. EU's Green Deal inkluderer dette.</div>`},
        {id:'geo10-6',title:'Bæredygtigt landbrug',icon:'🌾',tags:['agroøkologi','permaculture','regenerativt'],body:`<div class="def-box">Regenerativt landbrug: opbygger jordbundens kulstof, øger biodiversitet. Agroforestry: kombinerer landbrug og skov. Reducerer kunstgødning og pesticidbehov.</div>`},
        {id:'geo10-7',title:'Smart farming og teknologi',icon:'🤖',tags:['drone','sensor','præcisionslandbrug'],body:`<div class="def-box">Præcisionslandbrug bruger sensorer, droner og AI til at optimere gødning, vanding og pesticidanvendelse. Reducerer ressourceforbrug og miljøbelastning.</div>`},
        {id:'geo10-8',title:'Vertikalt landbrug',icon:'🏢',tags:['vertikalt','indendørs','LED'],body:`<div class="def-box">Vertikalt landbrug: dyrkning i kontrolerede indendørs miljøer med LED-lys og hydroponik. Bruger 95% mindre vand, ingen pesticider, men kræver meget energi.</div>`},
        {id:'geo10-9',title:'Hav som ressource',icon:'🐟',tags:['fiskeri','overfiskeri','havbrug'],body:`<div class="def-box">Over 90% af fiskebestande er fuldt udnyttede eller overfiskede. MSC-certificering fremmer bæredygtigt fiskeri. Havbrug (akvakultur) vokser som alternativ.</div>`},
        {id:'geo10-10',title:'Kritiske mineraler',icon:'⛏️',tags:['lithium','kobolt','sjælden'],body:`<div class="def-box">Grøn teknologi kræver: lithium (batterier), kobolt (EV), sjældne jordarter (vindmøller). Udvindes primært i Kina, DRC og Chile. Geopolitisk sårbarhed.</div>`},
        {id:'geo10-11',title:'Brint som energibærer',icon:'⚗️',tags:['grøn brint','elektrolyse','brændselscelle'],body:`<div class="def-box">Grøn brint: elektrolyse af vand med vedvarende el → H₂. Bruges i brændselsceller (bil, industri). Potentiale til at erstatte fossile brændstoffer i tung industri.</div>`},
        {id:'geo10-12',title:'Geopolitik og energiressourcer',icon:'🛢️',tags:['OPEC','energisikkerhed','gas'],body:`<div class="def-box">OPEC kontrollerer 40% af verdens oliproduktion. Rusland-Ukraine-krigen viste Europas afhængighed af russisk gas. Energisikkerhed er et nationalt sikkerhedsspørgsmål.</div>`},
        {id:'geo10-13',title:'Klimamigration',icon:'🌊',tags:['klimaflygtning','øer','kystbyer'],body:`<div class="def-box">Lavtliggende øer (Maldiverne, Tuvalu) oversvømmes ved 1,5°C opvarmning. 1 mia. kan tvinges til at flygte inden 2050. Juridisk status af klimaflygtninge uafklaret.</div>`},
        {id:'geo10-14',title:'Demografisk dividende',icon:'👥',tags:['ung befolkning','arbejdsstyrke','vækst'],body:`<div class="def-box">Demografisk dividende: når en ung befolkning når arbejdsalder → øget produktivitet → vækst. Afrika har verdens yngste befolkning. Afgørende om uddannelse og job følger.</div>`},
        {id:'geo10-15',title:'Gentrifikation',icon:'🏙️',tags:['gentrifikation','byfornyelse','boligpris'],body:`<div class="def-box">Gentrifikation: velstillede grupper overtager fattigere bykvarterer → stigende huslejer → fordrivelse af eksisterende beboere. Ses i København, London, New York.</div>`},
        {id:'geo10-16',title:'Urbaniseringens miljøpåvirkning',icon:'🏭',tags:['urban heat island','forurening','impervious'],body:`<div class="def-box">Urban heat island: byer er varmere end omland pga. asfalt og bygninger. Grønne tage, træer og vandflader mindsker effekten. Urban runoff forurener vandmiljøer.</div>`},
        {id:'geo10-17',title:'Kyoto-protokollen og UNFCCC',icon:'📄',tags:['Kyoto','UNFCCC','emissionshandel'],body:`<div class="def-box">Kyoto-protokollen (1997): bindende CO₂-reduktionsmål for industrilande. UNFCCC: FN's klimakonvention der faciliterer klimaforhandlingerne (COP-møder).</div>`},
        {id:'geo10-18',title:'Carbon footprint og livsstil',icon:'👣',tags:['carbon footprint','kødforbrug','fly'],body:`<div class="def-box">Gennemsnitlig danskers CO₂-aftryk: ~12 ton/år. Størst bidrag: fly (1 flyvning = 1-2 ton), kød (oksekød: 27 kg CO₂/kg) og opvarmning.</div>`},
        {id:'geo10-19',title:'Carbon capture og lagring (CCS)',icon:'🌱',tags:['CCS','DAC','CO₂-lagring'],body:`<div class="def-box">CCS: fanger CO₂ fra kraftværker og lagrer det under jord. DAC (Direct Air Capture): fjerner CO₂ direkte fra atmosfæren. Dyrt men nødvendigt for netto-nul.</div>`},
        {id:'geo10-20',title:'Skovrejsning og CO₂',icon:'🌲',tags:['skovrejsning','sekvestrering','biodiversitet'],body:`<div class="def-box">Skovrejsning binder CO₂. Men det er ikke nok alene til at løse klimakrisen. Bevarelse af eksisterende urskov er vigtigere end nyplantning.</div>`},
        {id:'geo10-21',title:'Geopolitik i Arktis',icon:'🧊',tags:['Arktis','arktis-politik','ressourcer'],body:`<div class="def-box">Smeltende Arktis åbner nye sejlruter (Nordvejpassagen) og ressourcer. Russland, USA, Canada, Norge og Danmark (Grønland) konkurrerer om indflydelse.</div>`},
        {id:'geo10-22',title:'Grønland og Arktis',icon:'🏔️',tags:['Grønland','isdæke','ressourcer'],body:`<div class="def-box">Grønland er verdens største ø (2,16 mio. km²). 80% isdækket. Selvstyre 2009. Enorme mineralressourcer og strategisk beliggenhed giver geopolitisk interesse.</div>`},
        {id:'geo10-23',title:'Nanoteknologi og geografi',icon:'🔬',tags:['nanomateriale','solcelle','effektivitet'],body:`<div class="def-box">Nanomaterialer (grafen, perovskitter) øger solcelleeffektiviteten. Nanoteknik forbedrer vandrensning og filtrering. Fremtiden for grøn teknologi afhænger af materialeinnovation.</div>`},
        {id:'geo10-24',title:'Digital økonomi og geografi',icon:'💻',tags:['Silicon Valley','datacenter','digital'],body:`<div class="def-box">Digital økonomi er koncentreret geografisk: Silicon Valley, Shenzhen, London. Datacentre kræver store mængder vand og energi. Digital ulighed: 3 mia. offline.</div>`},
        {id:'geo10-25',title:'AI og fremtidens arbejdsmarked',icon:'🤖',tags:['AI','automatisering','arbejde'],body:`<div class="def-box">AI automatiserer rutinearbejde. McKinsey: op til 30% af opgaver kan automatiseres inden 2030. Geografi afgør hvilke lande der profiterer og hvem der rammes.</div>`},
        {id:'geo10-26',title:'Koralrev og klimaforandringer',icon:'🐠',tags:['koraller','bleaching','Great Barrier Reef'],body:`<div class="def-box">Koralblegning sker ved >1°C over normalt. Great Barrier Reef har oplevet 6 masseblegnin-hændelser siden 1998. Koralrev huser 25% af alle marine arter.</div>`},
        {id:'geo10-27',title:'Permafrost og metanudslip',icon:'🌡️',tags:['permafrost','metan','tipping point'],body:`<div class="def-box">Permafrost dækker 25% af jordens landoverflade og indeholder dobbelt så meget kulstof som atmosfæren. Optøning frigiver metan (CH₄) – 80× kraftigere drivhusgas end CO₂ på 20-årig horisont.</div>`},
        {id:'geo10-28',title:'Havvindmøller og placering',icon:'💨',tags:['havvind','Nordsøen','offshore'],body:`<div class="def-box">Nordsøen er ideal til havvindmøller: lavt vand, stærk vind. Danmark er frontløber. Havvind er billigste nye elproduktion globalt. Produktion: over 100 GW installeret globalt.</div>`},
        {id:'geo10-29',title:'One Health tilgang',icon:'🦠',tags:['One Health','zoonose','pandemi'],body:`<div class="def-box">One Health: menneskelig, dyrets og miljøets sundhed er forbundne. Afskovning → tættere kontakt med vilde dyr → øget zoonosesmitte (COVID-19, Ebola, SARS).</div>`},
        {id:'geo10-30',title:'Geografi og konflikt',icon:'🗺️',tags:['ressourcer','grænser','konflikt'],body:`<div class="def-box">Ressourcekonflikter: vand (Nil-konflikt), olie (Mellemøsten). Kolonigrænser skaber etniske konflikter (Afrika). Geografisk isolation begrænser udviklingsmuligheder (landindspærrende lande).</div>`},
      ]
    },
    'gym':{
      title:'Gymnasium',
      description:'Klimavidenskab, geopolitik og avanceret regionalgeografi.',
      topics:[
        {id:'geogym-1',title:'Energibalance og strålingsfordelingen',icon:'☀️',tags:['albedo','stråling','energibalance'],body:`<div class="formula-box">Indstråling = Udstråling (ligevægt)<br>Albedo: % af sol der reflekteres</div><p>Jordens globale energibalance bestemmer temperaturen.</p>`},
        {id:'geogym-2',title:'Havstrømme og termohalinecirkulation',icon:'🌊',tags:['AMOC','Gulf Stream','termohalin'],body:`<div class="def-box">Termohalinecirkulation (AMOC): drevet af saltindhold og temperatur. Gulf Stream varmer Nordeuropa. Svækkelse pga. ferskvandsindstrøm fra is truer Europas klima.</div>`},
        {id:'geogym-3',title:'Monsun og ITCZ',icon:'🌧️',tags:['monsun','ITCZ','Intertropisk'],body:`<div class="def-box">ITCZ (Inter-Tropical Convergence Zone): bælte af nedbør nær ækvator. Monsun: sæsonmæssig vending af vindretning → monsunsregn (Sydasien, Vestafrika).</div>`},
        {id:'geogym-4',title:'Klimatologi: dendrokronologi og iskerner',icon:'🌲',tags:['iskerne','dendro','palæoklima'],body:`<div class="def-box">Iskerner: lagdelt arkiv af palæoklima (temperatur via δ¹⁸O, CO₂ i bobler). Dendrokronologi: træringens bredde viser klimavariationer. EPICA: 800.000 år data.</div>`},
        {id:'geogym-5',title:'Stadsgeografi og landanvendelse',icon:'🗺️',tags:['GIS','landanvendelse','bystruktur'],body:`<div class="def-box">GIS (Geographic Information Systems): software til geografisk dataanalyse. Landanvendelsesmodeller: Chicago's koncentriske ringe, sektormodel, multinucleusmodel.</div>`},
        {id:'geogym-6',title:'Centralplads-teorien',icon:'🏙️',tags:['Christaller','centralplads','handelscentrum'],body:`<div class="def-box">Christallers centralplads-teori: byer er organiseret i et hierarki med regelmæssige afstande. Jo større by, jo mere specialiserede services og større opland.</div>`},
        {id:'geogym-7',title:'Gravity-modellen',icon:'🔗',tags:['gravitationsmodel','migration','interaktion'],body:`<div class="formula-box">I = k(P₁ × P₂)/d²<br>Interaktion proportional med befolkninger og omvendt proportional med afstand²</div>`},
        {id:'geogym-8',title:'Strukturel transformation',icon:'📊',tags:['primær','sekundær','tertiær'],body:`<div class="def-box">Udviklingsøkonomi: fra primær sektor (landbrug) → sekundær (industri) → tertiær (services) → kvartær (viden). Rostows moderniseringstrin.</div>`},
        {id:'geogym-9',title:'Verdenssystemteori',icon:'🌐',tags:['Wallerstein','kerne','periferi'],body:`<div class="def-box">Wallersteins verdenssystemteori: kerne (rige lande udnytter) → semi-periferi → periferi (råvarer). Struktur reproducerer ulighed.</div>`},
        {id:'geogym-10',title:'Afhængighedsteorien',icon:'🔗',tags:['afhængighed','imperialisme','struktur'],body:`<div class="def-box">Afhængighedsteori (Frank): u-landenes underudvikling er ikke manglende modernisering men aktivt produceret af i-landes udnyttelse. Modsat moderniseringsteori.</div>`},
        {id:'geogym-11',title:'Amartya Sen og kapabilitetsansatsen',icon:'🏫',tags:['kapabilitet','frihed','HDI'],body:`<div class="def-box">Amartya Sens kapabilitetsansats: udvikling = udvidelse af folks reelle friheder og muligheder. Grundlag for HDI. Uddannelse og sundhed er centrale.</div>`},
        {id:'geogym-12',title:'Miljøøkonomi og eksternaliteter',icon:'💰',tags:['eksternalitet','CO₂-afgift','Pigou'],body:`<div class="def-box">Eksternaliteter: bivirkninger der ikke afspejles i markedspriser. CO₂-emission: negativ eksternalitet. Løsning: Pigouviansk afgift = internalisering af de sociale omkostninger.</div>`},
        {id:'geogym-13',title:'Carrying capacity og overshoot',icon:'🌍',tags:['bæreevne','overshoot','jordens grænser'],body:`<div class="def-box">Earth Overshoot Day: dag på året hvor vi har brugt årets fornybare ressourcer. Rocköströms 9 planetariske grænser. Vi overskrider adskillige.</div>`},
        {id:'geogym-14',title:'Kina – geografi og økonomi',icon:'🇨🇳',tags:['Kina','BRI','vækst'],body:`<div class="def-box">Kina: verdens 2. økonomi, 1,4 mia. indbyggere. Belt and Road Initiative: global infrastruktur for indflydelse. Kinesisk vækst reducerede ekstrem fattigdom markant.</div>`},
        {id:'geogym-15',title:'Indien – geografi og demografi',icon:'🇮🇳',tags:['Indien','befolkning','urbanisering'],body:`<div class="def-box">Indien overgik Kina i befolkning (2023): 1,43 mia. Ung befolkning: demografisk dividende potentiale. Kastsystemets geografiske ulighed. Monsunafhængig økonomi.</div>`},
        {id:'geogym-16',title:'Mellemøsten – ressourcer og konflikter',icon:'🛢️',tags:['olie','Israel-Palæstina','vand'],body:`<div class="def-box">Mellemøsten: 50% af verdens oliereserver. Israel-Palæstina-konflikten: territorial og ressourcemæssig. Vandmangel (Jordan-floden) forværrer spændingerne.</div>`},
        {id:'geogym-17',title:'Subsaharisk Afrika',icon:'🌍',tags:['SSA','vækst','demografi'],body:`<div class="def-box">Sub-Sahara Afrika: hurtigst voksende region. Ressourceforbandelse i mange lande. Demografisk vækst: udfordring og mulighed. Kina er største handelspartner.</div>`},
        {id:'geogym-18',title:'EU og europæisk integration',icon:'🇪🇺',tags:['EU','Schengen','euroen'],body:`<div class="def-box">EU: 27 lande, fælles marked, Schengen-zone (26 lande). Eurozonen: 20 lande med fælles valuta. Brexit viste kompleksiteten i integration og desintegration.</div>`},
        {id:'geogym-19',title:'Migration og befolkningspolitik',icon:'👥',tags:['migration','anti-immigration','demografisk'],body:`<div class="def-box">Europa: aldrende befolkning → behov for indvandring. Politisk modstand mod migration stiger. Demografisk underskud vs. integrationsproblemer er et centralt dilemma.</div>`},
        {id:'geogym-20',title:'Globale bynetværk',icon:'🌐',tags:['global city','New York','finanscentrum'],body:`<div class="def-box">Global cities (Sassen): New York, London, Tokyo – knudepunkter for globalt finanskapital og services. Hierarki af bynetværk styrer globale strømme.</div>`},
        {id:'geogym-21',title:'Ressourcegeopolitik og sjælden jord',icon:'💎',tags:['sjælden jord','Kina','grøn teknologi'],body:`<div class="def-box">Kina kontrollerer 60%+ af sjælden jordsproduktion. Nødvendigt til vindmøller, EV og elektronik. Ressourcegeopolitik: forsyningssikkerhed er et sikkerhedsspørgsmål.</div>`},
        {id:'geogym-22',title:'Havrets og UNCLOS',icon:'⚓',tags:['UNCLOS','EEZ','havret'],body:`<div class="def-box">UNCLOS (1982): Eksklusiv Økonomisk Zone (EEZ) = 200 sømil. Stater har suverænitet over ressourcer. Sydkinesiske Hav: overlappende krav → konflikter.</div>`},
        {id:'geogym-23',title:'Biologisk mangfoldighed og hotspots',icon:'🦜',tags:['biodiversitet','hotspot','endemisk'],body:`<div class="def-box">Biodiversitetshotspots: 36 regioner med ekstraordinær artsrigdom og trussel (Madagaskar, Amazonas, Himalaya). Beskyttelse er mest omkostningseffektiv her.</div>`},
        {id:'geogym-24',title:'Klimaøkonomi og DICE-model',icon:'💰',tags:['Stern Review','Nordhaus','skadeomkostning'],body:`<div class="def-box">Nordhaus's DICE-model: optimal CO₂-afgift vs. klimaskader. Stern Review: klimaindsats er billigere end inaktivitet. Diskonterings-rate er det centrale stridspunkt.</div>`},
        {id:'geogym-25',title:'Geoengineering',icon:'🌡️',tags:['solar radiation management','CDR','risiko'],body:`<div class="def-box">Solar Radiation Management (SRM): injektion af sulfat i stratosfæren for at reflektere sol. CDR: fjernelse af CO₂. Geoengineering: kontroversiel nødplan. Risici: monsunforstyrrelse, moral hazard.</div>`},
        {id:'geogym-26',title:'Food systems og food miles',icon:'🚚',tags:['food miles','lokal mad','CO₂'],body:`<div class="def-box">Food miles: afstand mad rejser fra mark til tallerkenen. Lokal mad reducerer transport-CO₂ men er ikke altid bedste løsning (æbler fra UK vs. NZ). Produktionsmetode er vigtigere.</div>`},
        {id:'geogym-27',title:'Oceanografi og ARGO-floats',icon:'🌊',tags:['ARGO','havtemperatur','observationer'],body:`<div class="def-box">ARGO: 4.000+ autonome bøjer måler oceanets temperatur og saltindhold. Vigtig for klimamodeller og forståelse af varmelagring i havet.</div>`},
        {id:'geogym-28',title:'Remote sensing og satellitter',icon:'🛰️',tags:['Landsat','SAR','afskovning'],body:`<div class="def-box">Remote sensing: observation af Jordens overflade fra satellitter (Landsat, Sentinel, MODIS). Bruges til at overvåge afskovning, glacialsmelting, byudvikling.</div>`},
        {id:'geogym-29',title:'Naturgeografi: karst og kalksten',icon:'🏔️',tags:['karst','hule','stalaktit'],body:`<div class="def-box">Karsttopografi dannes ved opløsning af kalksten af svag kulsyre. Karakteristisk: huler, stalaktitter, stalagmitter, doliner. Ses i Slovenien, Kina og på Yucatán-halvøen.</div>`},
        {id:'geogym-30',title:'Geomorfologi: glasiale former',icon:'🧊',tags:['gletscher','fjord','drumlin'],body:`<div class="def-box">Gletschere former terrænet: fjorde (U-dale), drumlins (strømlinet morænebakke), ørret-bakker, morænelandskaber. Skandinavien er præget af istiden.</div>`},
      ]
    },
    'uni':{
      title:'Videregående',
      description:'Avanceret klimavidenskab, geopolitisk økonomi og miljøstyring.',
      topics:[
        {id:'geouni-1',title:'Klimadynamik: feedback og tipping cascades',icon:'🔄',tags:['tipping cascade','AMOC','Amazonas'],body:`<div class="def-box">Tipping cascades: multiple tipping points kan trigge hinanden (Arktis ice → Borealt skov → Amazonas → AMOC). Risiko for ikke-lineær klimaCollapse.</div>`},
        {id:'geouni-2',title:'Integrated Assessment Models',icon:'💻',tags:['IAM','SSP','modellering'],body:`<div class="def-box">IAMs (REMIND, IMAGE) kobler klima- og energisystemer. SSP-scenarier beskriver mulige fremtider (SSP1: bæredygtighed til SSP5: fossil-intensiv). Grundlag for IPCC AR6.</div>`},
        {id:'geouni-3',title:'Politisk økonomi og global governance',icon:'🏛️',tags:['governance','multilateralisme','IFI'],body:`<div class="def-box">Globale governance-institutioner: IMF, Verdensbanken, WTO. Kritik: demokratiunderskud, vestligt bias. Fremgang: kinesisk-ledet AIIB, BRICS-expansion.</div>`},
        {id:'geouni-4',title:'Politisk geografi og territorialitet',icon:'🗺️',tags:['territorium','stat','suverænitet'],body:`<div class="def-box">Territorialitet: staters kontrol over et afgrænset geografisk rum. Westfalsk suverænitet (1648). Udfordres af: globaliseringen, international lov og transnationale aktører.</div>`},
        {id:'geouni-5',title:'Critical geopolitics',icon:'⚔️',tags:['kritisk geopolitik','magt','diskurs'],body:`<div class="def-box">Kritisk geopolitik (Dalby, Ó Tuathail): undersøger hvordan geografisk viden produceres og bruges til at legitimere magt. Dekonstruerer "naturlige" geopolitiske kategorier.</div>`},
        {id:'geouni-6',title:'Postkolonial geografi',icon:'🌍',tags:['postkolonial','dekolonisering','viden'],body:`<div class="def-box">Postkolonial geografi: kritiserer eurocentrisk geografisk viden. Frantz Fanon, Edward Said. Dekolonisering af curriculum: inkluder subalterne stemmer og perspektiver.</div>`},
        {id:'geouni-7',title:'Humboldt og geografihistorie',icon:'📜',tags:['Humboldt','geografi','historia'],body:`<div class="def-box">Alexander von Humboldt: grundlæggere af moderne geografi. Holistisk tilgang: klimazoner, plantedistribution, vertikalzoner. Cosmos (1845-62): syntetiserer naturvidenskab.</div>`},
        {id:'geouni-8',title:'GIS og spatial analysis',icon:'💻',tags:['GIS','spatial','raster'],body:`<div class="def-box">GIS bruger vector (punkter, linjer, polygoner) og raster (pixelgrid) data. Spatial analysis: overlay, buffer, interpolation. QGIS (open source), ArcGIS (kommerciel).</div>`},
        {id:'geouni-9',title:'Machine learning i geografi',icon:'🤖',tags:['ML','fjerndetection','klassificering'],body:`<div class="def-box">Random forests og deep learning (CNN) klassificerer fjernsensingebilleder: afskovning, urban vækst, habitatkortlægning. Google Earth Engine skalerer analyser globalt.</div>`},
        {id:'geouni-10',title:'Kvantitativ revolution og spatial science',icon:'📊',tags:['kvantitativ','spatial science','regression'],body:`<div class="def-box">1950-60'ernes kvantitative revolution: geografi som nomtetisk videnskab. Spatial regression, spatial autocorrelation (Moran's I), kriging. Modsvar: humanistisk geografi.</div>`},
        {id:'geouni-11',title:'Assemblage theory og by',icon:'🏙️',tags:['assemblage','DeLanda','aktantnetværk'],body:`<div class="def-box">Assemblage-teori (DeLanda): byer er dynamiske assemblages af heterogene aktører (mennesker, teknologi, institutioner). Afviser metodologisk nationalisme.</div>`},
        {id:'geouni-12',title:'Planetary urbanization',icon:'🌐',tags:['planetary urbanisering','Lefebvre','Brenner'],body:`<div class="def-box">Brenners planetary urbanization: urbaniseringen er ikke begrænset til byer men omformer hele planten. Extended urbanization: landlige rum omstruktureres af urban kapital.</div>`},
        {id:'geouni-13',title:'Political ecology',icon:'🌿',tags:['political ecology','magtrelationer','ressource'],body:`<div class="def-box">Political ecology: studerer samspillet mellem politiske, sociale og miljømæssige processer. Hvem kontrollerer ressourcer? Hvem bærer miljøbyrder? (Robbins, Blaikie).</div>`},
        {id:'geouni-14',title:'Socioøkologiske systemer',icon:'🔄',tags:['SES','resiliens','Ostrom'],body:`<div class="def-box">Elinor Ostroms socioøkologiske systemer (SES): fællesressourcer kan forvaltes bæredygtigt uden privatisering eller statslig kontrol via lokale institutioner (commons).</div>`},
        {id:'geouni-15',title:'Metabolic rift og agroøkologi',icon:'🌾',tags:['metabolic rift','Marx','jordfrugtbarhed'],body:`<div class="def-box">Marxs metabolic rift: industrialiseringen bryder det stofskifte der genanvender næringsstoffer. John Bellamy Foster: grundlag for socialistisk-økologisk kritik.</div>`},
        {id:'geouni-16',title:'Oceanografi: ENSO og klimapåvirkning',icon:'🌊',tags:['ENSO','El Niño','global'],body:`<div class="def-box">ENSO (El Niño–Southern Oscillation): 3-7 årige cykluser der påvirker globale nedbørsmønstre. El Niño (varmt) og La Niña (koldt). Forstærkes af klimaforandringer.</div>`},
        {id:'geouni-17',title:'Atmosfærisk kemi og ozonlag',icon:'🔬',tags:['ozon','CFC','Montreal-protokollen'],body:`<div class="def-box">Ozonsfrednin: CFC'er nedbryder O₃ via kloratomer. Montreal-protokollen (1987): forbud mod CFC. Ozonsfrednin er ved at hele sig – succeseksempel på global governance.</div>`},
        {id:'geouni-18',title:'Biogeografi: spredning vs. vikaariance',icon:'🌍',tags:['biogeografi','vikariance','spredning'],body:`<div class="def-box">Dispersal biogeography: arter spreder sig til nye områder. Vikariance biogeography: geografisk isolation splitter populations. Wallace-linjen i Indonesien er klassisk eksempel.</div>`},
        {id:'geouni-19',title:'Glaciologi og massebalance',icon:'🧊',tags:['glaciologi','massebalance','accumulation'],body:`<div class="def-box">Massebalance = akkumulation (sne) - ablation (smeltning). Negativ massebalance: gletscher trækker sig tilbage. GRACE-satellit måler tyngdeforandringer → massebalance.</div>`},
        {id:'geouni-20',title:'Hydrologiske modeller',icon:'💧',tags:['VIC','HBV','hydrologi'],body:`<div class="def-box">HBV-modellen: bucket-model for vandbalance. VIC: variable infiltration capacity – bruges til klimaprojektioner. SWAT: landbrugets effekt på vandkvalitet.</div>`},
        {id:'geouni-21',title:'Soil geography og pedogenese',icon:'🌱',tags:['jordbund','pedogenese','profil'],body:`<div class="def-box">Pedogenese: jorddannelsesprocesser (forvitring, humusakkumulering, podsolisering). FAO's World Reference Base: global klassifikation. Jordbund er ikke-fornybar ressource.</div>`},
        {id:'geouni-22',title:'Havniveaumodeller og SLRR',icon:'🌊',tags:['havstigning','IPCC','is'],body:`<div class="def-box">Sea Level Rise: IPCC AR6: 0,43–0,84 m inden 2100 (middel). Thermal expansion + issmeltning. Ice sheet instability kan give 2+ m. SLRR (Sea Level Rise Rate) accelererer.</div>`},
        {id:'geouni-23',title:'Agroøkosystemers diversitet',icon:'🌾',tags:['agroøkosystem','monokultur','polykultur'],body:`<div class="def-box">Monokultur: effektiv men sårbar. Polykultur og agroforestry: robust, biodiversitetsstøttende, CO₂-bindende. Traditionel viden integrerer biodiversitet i produktionssystemer.</div>`},
        {id:'geouni-24',title:'Green New Deal og transformation',icon:'♻️',tags:['Green New Deal','just transition','dekarbonisering'],body:`<div class="def-box">Green New Deal: politisk program for grøn økonomi + social retfærdighed. Just transition: sikre arbejdere i fossile industrier. EU Taxonomy: klassificerer grønne investeringer.</div>`},
        {id:'geouni-25',title:'Geografi og epidemiologi',icon:'🦠',tags:['epidemiologi','GIS','pandemi'],body:`<div class="def-box">Geografisk epidemiologi: kortlægger sygdomsmønstre. John Snow: første GIS-brug (kolera, 1854). COVID-19: geografi og ulighed bestemte dødelighedsmønstre.</div>`},
        {id:'geouni-26',title:'Geopolitik og cyberspace',icon:'💻',tags:['cyber','geopolitik','splinternet'],body:`<div class="def-box">Cyberspace som geopolitisk arena. Kinas Store Firewall: fragmenteret internet (splinternet). Kabelinfrastruktur: 95% af global datatrafik via undersøiske kabler. Ny form for territorialitet.</div>`},
        {id:'geouni-27',title:'Doughnut økonomi',icon:'🍩',tags:['doughnut','Raworth','sociale bundner'],body:`<div class="def-box">Kate Rawortsh doughnut-økonomi: det sikre og retfærdige rum mellem sociale fundament (minim. velvære) og planetarisk loft (miljøgrænser). Alternativ til BNP-vækstmål.</div>`},
        {id:'geouni-28',title:'Regenerative economies',icon:'🌿',tags:['regenerativ','biomimicry','circular'],body:`<div class="def-box">Regenerativ økonomi: systemer der genskaber naturligt kapital i stedet for kun at redde det. Biomimicry: lær af naturens løsninger. Permakultur som designprincipper.</div>`},
        {id:'geouni-29',title:'Futures geography og scenario planning',icon:'🔮',tags:['scenarieplanlægning','fremtid','usikkerhed'],body:`<div class="def-box">Scenarieplanlægning: multiple fremtider baseret på nøgleusikkerheder. Shell's scenariometode. Futures geography: rumlige dimensioner af mulige og foretrukne fremtider.</div>`},
        {id:'geouni-30',title:'Krisekartografi og humanitær geografi',icon:'🗺️',tags:['krise','kortlægning','humanitarian'],body:`<div class="def-box">Humanitær geografi: kortlægning under kriser. OpenStreetMap-frivillige kortlægger katastroferamte områder. Missing Maps: forbered kredsløb kortlægning til fremtidige katastrofer.</div>`},
      ]
    },
  }
};
